import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderCancelled;
import com.wolinski.shop.orders.api.OrderFacade;
import com.wolinski.shop.orders.api.OrderSummary;
import java.time.Instant;
import java.util.UUID;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService implements OrderFacade {

    private final OrderRepository orders;
    private final ApplicationEventPublisher events;

    public OrderService(OrderRepository orders, ApplicationEventPublisher events) {
        this.orders = orders;
        this.events = events;
    }

    @Override
    @Transactional
    public String place(String customerId, Money total, Instant placedAt) {
        Order order = new Order(UUID.randomUUID().toString(), customerId, total, placedAt);
        orders.save(order);
        return order.id();
    }

    @Override
    @Transactional
    public void confirm(String orderId) {
        orders.get(orderId).changeStatus("CONFIRMED");
    }

    @Override
    @Transactional
    public void cancel(String orderId) {
        Order order = orders.get(orderId);
        if ("CANCELLED".equals(order.status())) {
            return; // already cancelled: the customer was told once, do not announce it again
        }
        order.changeStatus("CANCELLED");
        events.publishEvent(new OrderCancelled(order.id(), order.customerId()));
    }

    @Override
    @Transactional(readOnly = true)
    public OrderSummary summary(String orderId) {
        Order order = orders.get(orderId);
        return new OrderSummary(order.id(), order.customerId(), order.total(), order.status());
    }
}
}

{path=src/main/java/com/wolinski/shop/notifications/internal/CancellationNotifications.java, content=package com.wolinski.shop.notifications.internal;

import com.wolinski.shop.customers.api.CustomerFacade;
import com.wolinski.shop.notifications.api.Notifier;
import com.wolinski.shop.orders.api.OrderCancelled;
import org.springframework.stereotype.Component;
import org.springframework.transaction.event.TransactionPhase;
import org.springframework.transaction.event.TransactionalEventListener;

@Component
public class CancellationNotifications {

    private final Notifier notifier;
    private final CustomerFacade customers;

    public CancellationNotifications(Notifier notifier, CustomerFacade customers) {
        this.notifier = notifier;
        this.customers = customers;
    }

    // After commit: the mail is a remote call and must not run inside the cancelling transaction (ADR 0005).
    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    void on(OrderCancelled cancelled) {
        String address = customers.emailOf(cancelled.customerId());
        if (address == null) {
            return; // no registered address to send to
        }
        notifier.send(address,
                "Order " + cancelled.orderId() + " cancelled",
                "Your order " + cancelled.orderId() + " has been cancelled.");
    }
}
}

