import com.wolinski.shop.notifications.api.MailTransport;
import java.util.ArrayList;
import java.util.List;
import org.springframework.context.annotation.Primary;
import org.springframework.stereotype.Component;

/** Test double that keeps every delivered mail so tests can inspect them. */
@Primary
@Component
class RecordingMailTransport implements MailTransport {

    record Mail(String address, String subject, String body) {
    }

    private final List<Mail> sent = new ArrayList<>();

    @Override
    public synchronized void deliver(String address, String subject, String body) {
        sent.add(new Mail(address, subject, body));
    }

    synchronized List<Mail> sent() {
        return List.copyOf(sent);
    }
}
}

